const assert=require('node:assert/strict'),fs=require('fs'),vm=require('vm'),path=require('path');
const M=require('../model.js'),UI=require('../c2.js'),{fixture}=require('./dom_fixture.cjs');
const ctx={window:{}};vm.runInNewContext(fs.readFileSync(path.join(__dirname,'../data/bundle.js'),'utf8'),ctx);const d=ctx.window.C2_DATA,m=M.build(d.schema,d.mapping);let checks=0;
function test(n,f){f();checks++;console.log('PASS',n)}
test('72 nodes: 59 originals, 13 instances, 47 answers, six unresolved',()=>{assert.equal(m.schema.nodes.length,59);assert.equal(m.nodes.size,72);assert.equal(m.answers.size,47);assert.equal(m.questions.length,6);assert.equal(M.validate(m).length,0)});
test('entry shows complete root and all five sections, no preselected deep answer',()=>{const s=M.initial(m);assert.equal(s.focus,M.ROOT);assert.equal(s.selected,M.ROOT);assert.equal(M.branch(m,s).items.length,5)});
test('every node and page bounded at 220/296/366/560/800/1200, no horizontal overflow or overlap',()=>{for(const width of [220,296,366,560,800,1200])for(const id of m.nodes.keys()){let s=M.locate(m,M.initial(m),id);for(let page=0;page<=M.branch(m,s).maxPage;page++){s=M.reduce(m,s,{type:'page',page});const g=M.layout(m,s,width);assert.equal(g.width,width);for(const n of g.nodes){assert(n.x>=0&&n.y>=0);assert(n.x+n.w<=width);assert(n.y+n.h<=g.height)}for(let i=0;i<g.nodes.length;i++)for(let j=i+1;j<g.nodes.length;j++){const a=g.nodes[i],b=g.nodes[j];assert(a.x+a.w<=b.x||b.x+b.w<=a.x||a.y+a.h<=b.y||b.y+b.h<=a.y)}}}});
test('all five global buttons persist at every selected node with explicit active branch',()=>{for(const id of m.nodes.keys()){const s=M.locate(m,M.initial(m),id),h=UI.overviewHtml(m,s);assert.equal((h.match(/class="c2-global-branch /g)||[]).length,5);for(const sec of M.SECTIONS)assert(h.includes('data-id="'+sec+'"'));assert.equal((h.match(/aria-current="true"/g)||[]).length,id===M.ROOT?0:1)}});
test('every layer item reachable across pages and complete directory search',()=>{for(const id of m.nodes.keys()){let s=M.locate(m,M.initial(m),id);s.focus=id;const seen=[];for(let page=0;page<=M.branch(m,s).maxPage;page++){s=M.reduce(m,s,{type:'page',page});seen.push(...M.branch(m,s).items.map(n=>n.id))}assert.deepEqual(seen,M.children(m,id).map(n=>n.id))}assert.equal(M.search(m).length,72)});
function start(){const f=fixture();assert.equal(f.errors.length,0);f.c2.open('harnessvln',f.app.getContext());return f;}
test('DOM: five main branches visible from initial root',()=>{const f=start();assert.equal(f.$$('.c2-global-branch').length,5);assert.equal(f.c2.getState().focus,M.ROOT);assert(f.$('.c2-canvas'));assert.equal(f.$('#c2-overlay'),null)});
test('DOM: global→Method→module1→why→evidence; global remains and close returns position',()=>{const f=start();f.click('.c2-global-branch[data-id="method"]');assert.equal(f.c2.getState().focus,'method');f.click('.c2-node[data-id="method.module1"]');f.click('.c2-node[data-id="method.module1.why"]');assert.equal(f.$$('.c2-global-branch').length,5);assert(f.$('.c2-mini-current').textContent.includes('为什么能work'));f.click('[data-c2="evidence"]');assert(f.$('#c2-drawer-body').textContent.includes('读者解释'));f.click('[data-c2="close"]');assert.equal(f.c2.getState().selected,'method.module1.why');f.click('[data-c2="overview"]');assert.equal(f.c2.getState().focus,M.ROOT)});
test('DOM: all unresolved including missing source remain visible',()=>{const f=start();f.click('[data-c2="unresolved"]');assert.equal(f.$$('.c2-question').length,6);assert(f.$('#c2-drawer-body').textContent.includes('源码尚未阅读'))});
test('DOM: complete directory and empty search recover',()=>{const f=start();f.click('[data-c2="directory"]');assert.equal(f.$$('.c2-directory-row').length,72);f.c2.dispatch({type:'search',query:'no-match-049390'});assert.equal(f.$$('.c2-directory-row').length,0);f.click('[data-c2="clear-search"]');assert.equal(f.$$('.c2-directory-row').length,72)});
test('DOM: history back/forward preserves branch and returns overview',()=>{const f=start();f.click('.c2-global-branch[data-id="method"]');f.click('.c2-node[data-id="method.module1"]');f.back();assert.equal(f.c2.getState().focus,'method');f.forward();assert.equal(f.c2.getState().focus,'method.module1');f.click('[data-c2="overview"]');assert.equal(f.c2.getState().focus,M.ROOT)});
test('document scroll repositions new layers and restores each history location (mock rectangles)',()=>{const f=start(),proto=Object.getPrototypeOf(f.$('#c2-focus-title'));f.window.innerHeight=900;f.window.scrollY=800;f.window.scrollTo=(x,y)=>{f.window.scrollY=typeof x==='object'?x.top:y;};proto.getBoundingClientRect=function(){return {top:(this.id==='c2-focus-title'?450:100)-f.window.scrollY,height:this.className==='c2-overview'?180:30}};f.click('.c2-global-branch[data-id="method"]');assert.equal(f.window.scrollY,252);f.window.scrollY=1000;f.click('.c2-node[data-id="method.module1"]');assert.equal(f.window.scrollY,252);f.window.scrollY=700;f.back();assert.equal(f.window.scrollY,1000);f.window.innerHeight=500;f.window.scrollY=800;f.click('.c2-global-branch[data-id="experiments"]');assert.equal(f.$('.c2-overview').style.position,'relative');assert.equal(f.window.scrollY,432);f.window.innerHeight=900;f.window.scrollY=800;f.click('[data-c2="overview"]');assert.equal(f.window.scrollY,92);delete proto.getBoundingClientRect;});
test('pending papers never inherit HarnessVLN evidence',()=>{const n=M.build(d.schema,d.mapping,'navgpt');assert.equal(n.nodes.size,59);assert.equal(n.answers.size,0);assert.equal(n.mapping,null)});
console.log(checks+' global-first contracts passed; deterministic DOM only, no browser geometry claimed');
